package org.protys.ws.service;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;
import org.springframework.test.util.ReflectionTestUtils;

/** Starts only a private loopback server and stores every generated byte in the test directory. */
final class IsolatedFusekiFixture implements AutoCloseable {
    final FusekiService client = new FusekiService();
    private final Process process;

    IsolatedFusekiFixture(Path directory) throws Exception {
        Path runtime = Path.of("../research/runtime/validator/target").toAbsolutePath().normalize();
        String classpath = runtime.resolve("classes") + java.io.File.pathSeparator
                + Files.readString(runtime.resolve("classpath.txt")).trim();
        Path port = directory.resolve("port.txt");
        Path error = directory.resolve("fuseki.stderr");
        process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin/java").toString(),
                "-cp", classpath, "org.protys.research.IsolatedFuseki", port.toString(), directory.resolve("tdb").toString())
                .redirectOutput(directory.resolve("fuseki.stdout").toFile()).redirectError(error.toFile()).start();
        try {
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
            while (!Files.exists(port) && process.isAlive() && System.nanoTime() < deadline) Thread.sleep(50);
            if (!Files.exists(port)) throw new IllegalStateException("Private Fuseki failed: " + Files.readString(error));
            ReflectionTestUtils.setField(client, "fusekiEndpoint", "http://127.0.0.1:" + Files.readString(port).trim() + "/academic");
        } catch (Exception errorStarting) {
            close();
            throw errorStarting;
        }
    }

    @Override public void close() throws Exception {
        process.destroy();
        if (!process.waitFor(5, TimeUnit.SECONDS)) {
            process.destroyForcibly();
            if (!process.waitFor(5, TimeUnit.SECONDS)) throw new IllegalStateException("Private Fuseki did not stop");
        }
    }
}
